const sections: PrayerSection[] = [{"id":"me-ein-shalosh","heading":"Me'ein Shalosh","lines":[{"he":"ברכה אחרונה"},{"he":"ברכה אחרונה מעין שלוש"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם:"},{"he":"על היין: עַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן:","note":true},{"he":"על פירות משבעת המינים: עַל הָעֵץ וְעַל פְּרִי הָעֵץ:","note":true},{"he":"על מזונות: עַל הַמִחְיָה וְעַל הַכַּלְכָּלָה:","note":true},{"he":"על מזונות ויין ביחד: עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה וְעַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן:","note":true},{"he":"וְעַל תְּנוּבַת הַשָּׂדֶה וְעַל אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה שֶׁרָצִיתָ וְהִנְחַלְתָּ לַאֲבוֹתֵינוּ לֶאֱכֹל מִפִּרְיָהּ וְלִשְׂבּוֹעַ מִטּוּבָהּ, רַחֵם (נָא) יְהֹוָה אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ וְעַל מִזְבְּחֶךָ וְעַל הֵיכָלֶךָ, וּבְנֵה יְרוּשָׁלַיִם עִיר הַקֹּדֶשׁ בִּמְהֵרָה בְּיָמֵינוּ וְהַעֲלֵנוּ לְתוֹכָהּ וְשַׂמְּחֵנוּ בְּבִנְיָנָהּ וְנֹאכַל מִפִּרְיָּהּ וְנִשְׂבַּע מִטּוּבָהּ וּנְבָרֶכְךָ עָלֶיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה:"},{"he":"(בשבת:) וּרְצֵה וְהַחֲלִיצֵנוּ בְּיוֹם הַשַּׁבָּת הַזֶּה:","note":true},{"he":"(בר\"ח:) וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם רֹאשׁ הַחֹדֶשׁ הַזֶּה:","note":true},{"he":"(בר\"ה:) וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם הַזִּכָּרוֹן הַזֶּה:","note":true},{"he":"(ביו\"ט:) וְשַׂמְחֵנוּ בְּיוֹם חַג (פלוני) הַזֶּה:","note":true},{"he":"כִּי אַתָּה יְהֹוָה טוֹב וּמֵטִיב לַכֹּל וְנוֹדֶה לְךָ עַל הָאָרֶץ וְעַל:"},{"he":"(על היין:) פְּרִי הַגָּפֶן: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל פְּרִי הַגָּפֶן: ( בא\"י וְעַל פְּרִי גַפְנָהּ):","note":true},{"he":"(על הפירות:) הַפֵּרוֹת: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל הַפֵּרוֹת: ( בא\"י וְעַל פֵּרוֹתֶיהָ):","note":true},{"he":"(על מזונות:) הַמִחְיָה: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל הַמִחְיָה וְעַל הַכַּלְכָּלָה:","note":true},{"he":"(על מזונות ויין ביחד:) הַמִּחְיָה וְעַל פְּרִי הַגָּפֶן: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל הַמִחְיָה וְעַל הַכַּלְכָּלָה וְעַל פְּרִי הַגָּפֶן: ( בא\"י וְעַל פְּרִי גַפְנָהּ):","note":true}]},{"id":"ha-etz","heading":"Ha'etz","lines":[{"he":"בורא פרי העץ"},{"he":"על כל פרי העץ מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָעֵץ:"}]},{"id":"ha-adamah","heading":"Ha'adamah","lines":[{"he":"בורא פרי האדמה"},{"he":"על פרי האדמה מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָאֲדָמָה:"}]},{"id":"shehakol","heading":"Shehakol","lines":[{"he":"ברכת שהכל"},{"he":"על בשר ודגים. חלב וביצה וגבינה. כמהין ופטריות וכדומה. גם על המשקים חוץ מיין אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ:"}]},{"id":"borei-nefashot","heading":"Borei Nefashot","lines":[{"he":"בורא נפשות"},{"he":"על פירות האילן חוץ מז' מינים ופירות האדמה וירקות ועל כל המשקין ועל דבר שאין גידולו מן הארץ מברכין אחר אכילתן זה:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן עַל כָּל מַה שֶׁבָּרָאתָ לְהַחֲיוֹת בָּהֶם נֶפֶשׁ כָּל חָי. בָּרוּךְ חֵי הָעוֹלָמִים:"}]},{"id":"shehecheyanu","heading":"Shehecheyanu","lines":[{"he":"ברכת שהחיינו"},{"he":"הלובש מלבוש חדש וכן האוכל פרי חדש הגדל בזמן קבוע בשנה ומתחדש משנה לשנה מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהֶחֱיָנוּ וְקִיְּמָנוּ וְהִגִּיעָנוּ לַזְמַן הַזֶּה:"}]},{"id":"fragrant-spices","heading":"Fragrant Spices","lines":[{"he":"ריח בשמים"},{"he":"על ריח בשמים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי בְשָׂמִים:"}]},{"id":"fragrant-herbs","heading":"Fragrant Herbs","lines":[{"he":"ריח טוב שבעשבים"},{"he":"על ריח טוב שבעשבים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא עִשְׂבֵּי בְשָׂמִים:"}]},{"id":"fragrant-shrubs","heading":"Fragrant Shrubs","lines":[{"he":"ריח טוב שבעצים"},{"he":"על ריח טוב שבעצים ושיחים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא עֲצֵי בְשָׂמִים:"}]},{"id":"fragrant-fruit","heading":"Fragrant Fruit","lines":[{"he":"ריח טוב שבפירות"},{"he":"על ריח טוב שבפירות מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּירוֹת:"}]},{"id":"fragrant-oils","heading":"Fragrant Oils","lines":[{"he":"שמן אפרסמון"},{"he":"על שמן אפרסמון מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא שֶׁמֶן עָרֵב:"}]},{"id":"lightning-thunder","heading":"Lightning & Thunder","lines":[{"he":"בִּרְכַּת ברקים ורעמים"},{"he":"על הברקים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, עוֹשֶׂה מַעֲשֶׂה בְּרֵאשִׁית:"},{"he":"על הרעמים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם:"}]},{"id":"seeing-rainbow","heading":"Seeing Rainbow","lines":[{"he":"בִּרְכַּת הקשת","en":"Blessing over a rainbow"},{"he":"הרואה קשת צריך לברך ברכה זו:","en":"One who sees a rainbow should recite this blessing:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, זוֹכֵר הַבְּרִית נֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ:","en":"Blessed are You, Lord our God, King of the universe, who remembers the covenant, is faithful with [God's] covenant, and is steady with [God's] word."}]},{"id":"seeing-ocean","heading":"Seeing Ocean","lines":[{"he":"הים הגדול"},{"he":"הרואה את הים הגדול מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, עֹשֶׂה אֶת הַיָּם הַגָּדוֹל:"}]},{"id":"blossoming-fruit-tree","heading":"Blossoming Fruit Tree","lines":[{"he":"בִּרְכַּת הָאִילָנוֹת"},{"he":"הרואה אילני מאכל (לפחות שני אילנות) בפריחתם בימי ניסן מברך פעם אחת בשנה:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁלֹּא חִסֵּר בְּעוֹלָמוֹ כְּלוּם, וּבָרָא בוֹ בְּרִיוֹת טוֹבוֹת וְאִילָנוֹת טוֹבוֹת, לֵהָנוֹת בָּהֶם בְּנֵי אָדָם:"}]},{"id":"various-blessings-of-praise","heading":"Various Blessings of Praise","lines":[{"he":"ברכות שונות"},{"he":"הרואה חכם גדול מישראל אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁחָלַק מֵחָכְמָתוֹ לִירֵיאָיו:"},{"he":"הרואה חכם גדול מאומות העולם אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁנָתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם:"},{"he":"הרואה מלך מישראל אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁחָלַק מִכְּבוֹדוֹ לִירֵיאָיו:"},{"he":"הרואה מלך מאומות העולם אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁנָתַן מִכְּבוֹדוֹ לְבָשָׂר וָדָם:"},{"he":"הרואה בתי כנסיות בחורבנן מברך דיין האמת, ובישובן מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מַצִיב גְּבוּל אַלְמָנָה:"},{"he":"הרואה מקום שנעשו בו ניסים לישראל, כגון מעברות הירדן וחומות יריחו אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁעָשָׂה נִיסִּים לַאֲבוֹתֵינוּ בַּמָּקוֹם הַזֶּה:"},{"he":"הרואה מקום שנעשה בו נס לו, או לרבו, או לאבותיו, או לאבותינו בכלל, מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁעָשָׂה לִי (לְרַבִּי, לַאֲבוֹתַי, לַאֲבוֹתֵינוּ) נֵס בַּמָּקוֹם הַזֶּה:"},{"he":"כשרואין בריה משונה, כגון גמד, וכושי וכדומה אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מְשַׁנֶּה הַבְּרִיּוֹת:"},{"he":"הרואה חבירו החביב לו אחר ל' יום מברך שהחיינו, ואחר י\"ב חודש מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מְחַיֶה הַמֵּתִים:"},{"he":"הרואה אילנות טובים ובריות נאות, מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁכָּכָה לוֹ בְּעוֹלָמוֹ:"},{"he":"מי שלא ראה קברי ישראל שלשים יום יברך בראייתם:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר יָצַר אֶתְכֶם בְּדִּין, וְזָן וְכִלְכֵּל אֶתְכֶם בְּדִּין, וְהֵמִית אֶתְכֶם בְּדִּין, וְיוֹדֵעַ מִסְפַּר כֻּלְּכֶם בְּדִין, וְעָתִיד לְהַחֲזִיר וּלְהַחֲיוֹתכֶם בַּדִּין. בָּרוּךְ אַתָּה יְהֹוָה מְחַיֵּה הַמֵּתִים:"},{"he":"בפעם הראשונה שיורדים גשמים הרבה בארץ ישראל, ובחו\"ל לאחר עצירת גשמים שהיה העולם בצער מברך:","note":true},{"he":"מוֹדִים אֲנַחְנוּ לָךְ יְהֹוָה אֱלֹהֵינוּ על כל טפה וטפה שהורדת לנו וְאִלּוּ פִינוּ מָלֵא שִׁירָה כַּיָּם. וּלְשׁוֹנֵנוּ רִנָּה כַּהֲמוֹן גַּלָּיו. וְשִׂפְתוֹתֵינוּ שֶׁבַח כְּמֶרְחֲבֵי רָקִיעַ. וְעֵינֵינוּ מְאִירוֹת כַּשֶּׁמֶשׁ וְכַיָּרֵחַ. וְיָדֵינוּ פְרוּשׂוֹת כְּנִשְׁרֵי שָׁמָיִם. וְרַגְלֵינוּ קַלּוֹת כָּאַיָּלוֹת. אֵין אֲנַחְנוּ מַסְפִּיקִים לְהוֹדוֹת לְךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. וּלְבָרֵךְ אֶת שִׁמְךָ מַלְכֵּנוּ. עַל אַחַת מֵאָלֶף אֶלֶף אַלְפֵי אֲלָפִים וְרִבֵּי רְבָבוֹת פְּעָמִים. הַטּוֹבוֹת נִסִּים וְנִפְלָאוֹת שֶׁעָשִׂיתָ עִם אֲבוֹתֵינוּ וְעִמָּנוּ: מִלְּפָנִים מִמִּצְרַיִם גְּאַלְתָּנוּ יְהֹוָה אֱלֹהֵינוּ. וּמִבֵּית עֲבָדִים פְּדִיתָנוּ. בְּרָעָב זַנְתָּנוּ. וּבְשָׂבָע כִּלְכַּלְתָּנוּ. מֵחֶרֶב הִצַּלְתָּנוּ. וּמִדֶּבֶר מִלַּטְתָּנוּ. וּמֵחֳלָיִם רָעִים וְרַבִּים וְנֶאֱמָנִים דִּלִּיתָנוּ: עַד הֵנָּה עֲזָרוּנוּ רַחֲמֶיךָ. וְלֹא עֲזָבוּנוּ חֲסָדֶיךָ יְהֹוָה אֱלֹהֵינוּ. וְאַל תִּטְּשֵׁנוּ יְהֹוָה אֱלֹהֵינוּ לָנֶצַח: עַל כֵּן אֵבָרִים שֶׁפִּלַּגְתָּ בָּנוּ. וְרוּחַ וּנְשָׁמָה שֶׁנָּפַחְתָּ בְּאַפֵּינוּ. וְלָשׁוֹן אֲשֶׁר שַׂמְתָּ בְּפִינוּ. הֵן הֵם. יוֹדוּ וִיבָרְכוּ וִישַׁבְּחוּ וִיפָאֲרוּ וִישׁוֹרְרוּ וִירוֹמְמוּ וְיַעֲרִיצוּ וְיַקְדִּישׁוּ וְיַמְלִיכוּ אֶת שִׁמְךָ מַלְכֵּנוּ. בָּרוּךְ אַתָּה יְהֹוָה אֵל רוֹב הַהוֹדָאוֹת:"},{"he":"ובא\"י אם השנים כתיקונן יברך בלא שם ומלכות (עי' מ\"ב סי' רכא סק\"א ובבה\"ל שם):","note":true},{"he":"על פדיון פטר חמור יברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל פִּדְיוֹן פֶּטֶר חֲמוֹר:"}]},{"id":"immersing-utensils","heading":"Immersing Utensils","lines":[{"he":"בִּרְכַּת טְבִילַת כְּלִים"},{"he":"כשטובל כלים חדשים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל טְבִילַת כֶּלִי: (כשהם הרבה אומר: כֵּלִים:)"}]},{"id":"mezuzah","heading":"Mezuzah","lines":[{"he":"בִּרְכַּת הַמְזוּזָה"},{"he":"הקובע מזוזה מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִקְבֹּעַ מְזוּזָה:"}]},{"id":"separating-challah","heading":"Separating Challah","lines":[{"he":"סֵדֶר הַפְרָשַׁת חַלָּה"},{"he":"א. בזמנינו שהחלה אסורה באכילה לכהנים מפני הטומאה, לֹא נותנים אוֹתה לכהנים אלא שורפים אוֹתה. ומפרישים רק כל שהוא מבלי כל שיעור.","note":true},{"he":"ב. את החלה שמפרישים צריך לשרוף, ואסור לזורקה לאשפה ולזלזל בקדושתה. ורק לאחר ששרפה אוֹתה מותר לזורקה לאשפה, כיון שכבר נעשה מצוותה, ואין בזה משום זלזול. ואם אין אפשרות לשורפה, תכרוך את החלה פעמיים בנייר ותכניסה לפח הזבל."},{"he":"ג. טוב להמתין מלהפריש חלה עד לאחר גמר הלישה - כשתֵעשה העיסה גוש אחד. ואם לֹא הפרישה מן העיסה ואפתה - מפרישה מן הפת לאחר האפיה."},{"he":"ד. אין חיוב הפרשת חלה אלא מעיסה העומדת לאפיה. אבל העושה עיסה כדי לבשלה אוֹ לטגנה, מפרישה ממנה חלה בלי ברכה, ורק אם רוצה לאפות קצת ממנה - מפרישה ממנה חלה בברכה."},{"he":"ה. שעור הפרשת חלה בברכה הוא כשיש בקמח שיעור של 1560 גר', וממדת חסידות טוב להפריש חלה בלי ברכה משיעור קילו וחצי לערך (שו\"ת חזו\"ע עמ' תקיח). ולשיטת החזו\"א השעור הוא 2250 גר'."},{"he":"קודם ההפרשה מברכת:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ לְהַפְרִישׁ חַלָּה מִן הָעִיסָה:"},{"he":"ואחר כך לוקחת חתיכה כל שהיא ומרימה ביד ימין ואומרת:","note":true},{"he":"הֲרֵי זוֹ חַלָּה:"}]},{"id":"separating-terumot-maasrot","heading":"Separating Terumot & Maasrot","lines":[{"he":"סֵדֶר הַפְרָשַׁת תְּרוּמוֹת וּמַעַשְׂרוֹת"},{"he":"כל גידולי קרקע הגדלים בארץ יִשְׂרָאֵל בבעלות יהודי, חייבים בתרומות ומעשרות. וכל גידול קרקע שאינו ידוע אם הופרשו ממנו תרומות ומעשרות אוֹ לֹא, הרי הוּא בחזקת דמאי, וחייב להפריש ממנו תרומות ומעשרות בלי ברכה. ואם ודאי שלא הופרשו ממנו תרומות ומעשרות מפריש בברכה, דהיינו שלפני שיפריש יברך את הברכה ואחר כך יאמר את נוסח ההפרשה:","note":true},{"he":"סדר הפרשת תרומות ומעשרות עפ\"י פסקי החזון איש זצ\"ל","note":true},{"he":"נוטל מן הפרות יותר מאחד ממאה ומבדילו מן השאר ואומר:","note":true},{"he":"אם הפירות טבל ודאי יאמר לפני הנוסח:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַפְרִישׁ תְּרוּמוֹת וּמַעְשְׂרוֹת.","note":true},{"he":"יוֹתֵר מֵאֶחָד מִמֵּאָה שֶׁיֵּשׁ כַּאן הֲרֵי הוּא תְּרוּמָה גְּדוֹלָה בְּצַד צְפוֹנוֹ [כָּל מִין עַל מִינוֹ], אוֹתוֹ אֶחָד מִמֵּאָה שֶׁיֵּשׁ כַּאן וְעוֹד תִּשְׁעָה חֲלָקִים כְּמוֹתוֹ בְּצַד צְפוֹנוֹ שֶׁל הַפֵּירוֹת [כָּל מִין עַל מִינוֹ] הֲרֵי הוּא מַעֲשֵׂר רִאשׁוֹן. אוֹתוֹ אֶחָד מִמֵּאָה שֶׁעֲשִׂיתִיו מַעֲשֵׂר רִאשׁוֹן עָשׂוּי תְּרוּמַת מַעֲשֵׂר [כָּל מִין עַל מִינוֹ] וּמַעֲשֵׂר שֵׁנִי בְּצַד דְּרוֹמוֹ [כָּל מִין עַל מִינוֹ] [וְאִם צָרִיךְ מַעֲשֵׂר עָנִי יְהֵא מַעֲשֵׂר עָנִי בְּצַד דְּרוֹמוֹ.]","note":true},{"he":"אם הפירות טבל ודאי יאמר לפני הנוסח:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן מַעֲשֵׂר שֵׁנִי.","note":true},{"he":"אם הפירות ודאי נטע רבעי וטבל יאמר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל פִּדְיוֹן נֶטַע רְבָעִי.","note":true},{"he":"וּמְחוּלָל הוּא וְחוּמְשׁוֹ עַל שְׁתֵּי פְרוּטוּת שֶׁבִּרְשׁוּתִי לְחִילּוּל מַעֲשֵׂר שֵׁנִי וֶנֶטַע רְבָעִי.","note":true}]},{"id":"mealtime-blessings","heading":"Mealtime Blessings","lines":[{"he":"סדר סעודה וברכותיה"},{"he":"קודם הסעודה יטול ידיו ויברך:","note":true},{"he":"שְׂאוּ יְדֵיכֶם קוֹדֶשׁ וּבָרְכוּ אֶת יְהֹוָה: וְאֶשָׂא כַפַּי אֶל מִצְוֹתֶיךָ אֲשֶׁר אָהַבְתִּי וְאָשִׂחָה בְחֻקֶּיךָ:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל נְטִילַת יָדָיִם:","en":"...Blessed are You, Lord our God, King of the universe, who has sanctified us with His commandments and Commanded us regarding the washing of hands."},{"he":"על הלחם מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ:"}]}];

